import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export type AppearanceTheme = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: AppearanceTheme;
  scale: number;
  dense: boolean;
  font: string;
}

interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEMES: { value: AppearanceTheme; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONTS = [
  { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
  { value: 'display', label: 'Fraunces' },
  { value: 'mono', label: 'JetBrains Mono' },
];

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    theme: 'system',
    scale: 100,
    dense: false,
    font: 'sans',
    ...defaultValue,
  });

  const update = (patch: Partial<AppearanceSettings>) => {
    setSettings((prev) => {
      const next = { ...prev, ...patch };
      onChange?.(next);
      return next;
    });
  };

  const themeLabel =
    THEMES.find((item) => item.value === settings.theme)?.label ?? '';

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {themeLabel}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ color: 'var(--jx-text-2)', fontSize: '13px' }}>Тема</span>
        <JxToggle
          items={THEMES}
          value={settings.theme}
          onValueChange={(value) => update({ theme: value as AppearanceTheme })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        placeholder="Выберите шрифт"
        options={FONTS}
        value={settings.font}
        onValueChange={(value) => update({ font: value })}
      />
    </section>
  );
}

